import"./hoisted.DWgf2xLV.js";import"./Toast.astro_astro_type_script_index_0_lang.DEjscZYH.js";const d=document.getElementById("contactForm"),s=document.getElementById("submitBtn"),n=document.getElementById("submitBtnText"),a=document.getElementById("submitBtnLoading"),e=document.getElementById("formMessage");d.addEventListener("submit",async o=>{o.preventDefault();const t=new FormData(d);t.get("name"),t.get("email"),t.get("subject"),t.get("message"),s.disabled=!0,n.classList.add("hidden"),a.classList.remove("hidden"),e.classList.add("hidden");try{await new Promise(r=>setTimeout(r,1500)),e.textContent="Thank you for your message! We will get back to you soon.",e.className="hidden p-4 rounded-lg text-center bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 border border-green-200 dark:border-green-800",e.classList.remove("hidden"),d.reset()}catch{e.textContent="Sorry, there was an error sending your message. Please try again.",e.className="hidden p-4 rounded-lg text-center bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-800",e.classList.remove("hidden")}finally{s.disabled=!1,n.classList.remove("hidden"),a.classList.add("hidden")}});
